html:
{% set ctx = get_fee_certificate_context(doc.name) %}
{% set settings = ctx.settings %}
{% set table = ctx.table %}
{% set is_multi_year = table.year_labels|length > 1 %}

<!DOCTYPE html>
<html>
<head>
	<meta charset="UTF-8">
	<style>
		/* Equal 15mm margin on all four sides (the print format's margin fields match). */
		@page {
			size: A4;
			margin: 15mm;
		}

		html, body { margin: 0; padding: 0; }

		/* Two-row table: content, then the letterhead footer pinned to the bottom
		   margin (wkhtmltopdf ignores position:fixed / flex). */
		table.fc-layout {
			width: 100%;
			border-collapse: collapse;
		}

		table.fc-layout > tbody > tr > td {
			padding: 0;
			vertical-align: top;
		}

		/* Keeps the footer on the bottom margin. wkhtmltopdf renders CSS at about 0.75
		   scale, so the PDF needs 328mm here; a real browser (JavaScript on; the PDF
		   generator runs with it off) switches to .fc-browser, which is 1:1. */
		table.fc-layout td.fc-layout-body {
			height: 328mm;
		}

		.fc-browser table.fc-layout td.fc-layout-body {
			height: 245mm;
		}

		table.fc-layout > tbody > tr.fc-layout-footer > td {
			vertical-align: bottom;
		}

		.fc-page {
			font-family: Cambria, Georgia, "Times New Roman", serif;
			font-size: 12pt;
			line-height: 1.85;
			color: #000;
		}

		.fc-header img.letterhead {
			width: 100%;
			display: block;
		}

		.fc-header.text-header {
			display: flex;
			align-items: center;
			border-bottom: 2px solid #6d1b3a;
			padding-bottom: 8px;
		}

		.fc-header.text-header img {
			height: 60px;
			margin-right: 16px;
		}

		.fc-header.text-header h1 {
			margin: 0;
			font-size: 16pt;
			color: #6d1b3a;
		}

		.fc-header.text-header .address {
			font-size: 8.5pt;
			line-height: 1.4;
		}

		.fc-content {
			padding: 0;
		}

		.date-line {
			text-align: right;
			margin: 8mm 0 4mm;
		}

		.title {
			text-align: center;
			text-decoration: underline;
			font-weight: bold;
			font-size: 13pt;
			margin-bottom: 14px;
		}

		.body-text {
			text-align: justify;
		}

		.body-text p, .bank-details p, .closing-text p {
			margin: 0 0 12px;
		}

		table.fee-table {
			width: 100%;
			border-collapse: collapse;
			margin: 4px 0 20px;
			line-height: 1.3;
		}

		table.fee-table th, table.fee-table td {
			border: 1px solid #000;
			padding: 5px 6px;
		}

		table.fee-table th {
			text-align: center;
			white-space: nowrap;
			font-weight: bold;
			color: #000;
		}

		table.fee-table td.amount {
			text-align: right;
			white-space: nowrap;
		}

		table.fee-table td.sl {
			text-align: center;
		}

		table.fee-table tr.total-row td, table.fee-table tr.net-row td {
			font-weight: bold;
		}

		.bank-details, .closing-text {
			text-align: justify;
		}

		.signature-block {
			margin-top: 8mm;
			text-align: right;
			line-height: 1.3;
		}

		/* Frappe's print CSS forces "body:last-child .print-format td img
		   { width: 100% !important }", which outranks these rules, so the width is
		   also set inline on the <img> tags (inline !important always wins). */
		.signature-block .signature {
			height: 24mm;
			width: auto !important;
			max-width: none;
			display: inline-block;
		}

		.signature-block .seal {
			height: 24mm;
			width: auto !important;
			max-width: none;
			display: block;
			margin-left: auto;
			margin-top: 6px;
		}

		.signature-block .designation {
			font-weight: bold;
		}

		.fc-footer {
			padding-top: 6mm;
		}

		.fc-footer img {
			width: 100%;
			display: block;
		}

		.fc-footer .footer-note {
			border-top: 1px solid #000;
			padding-top: 6px;
			font-size: 8pt;
			text-align: center;
		}
	</style>
</head>
<body>
<div class="fc-page">
<script>document.querySelector(".fc-page").classList.add("fc-browser");</script>
<table class="fc-layout"><tbody><tr><td class="fc-layout-body">
	{% if ctx.header_image %}
	<div class="fc-header">
		<img class="letterhead" src="data:image/png;base64,{{ ctx.header_image }}">
	</div>
	{% else %}
	<div class="fc-header text-header">
		{% if settings.institute_logo %}<img src="data:image/png;base64,{{ get_file_b64(settings.institute_logo) }}">{% endif %}
		<div>
			<h1>{{ settings.institute_name or "" }}</h1>
			<div class="address">{{ settings.institute_address or "" }}</div>
			<div class="address">
				{%- set contact_parts = [] -%}
				{%- if settings.institute_phone -%}{%- set _ = contact_parts.append("Telephone: " ~ settings.institute_phone) -%}{%- endif -%}
				{%- if settings.institute_website -%}{%- set _ = contact_parts.append("Website: " ~ settings.institute_website) -%}{%- endif -%}
				{%- if settings.institute_email -%}{%- set _ = contact_parts.append("Email: " ~ settings.institute_email) -%}{%- endif -%}
				{{ contact_parts|join("  |  ") }}
			</div>
		</div>
	</div>
	{% endif %}

	<div class="fc-content">
		<div class="date-line">{{ ctx.generation_date }}</div>

		<div class="title">{{ ctx.heading }}</div>

		<div class="body-text">{{ ctx.body_html }}</div>

		<table class="fee-table">
			<thead>
				<tr>
					<th style="width: {{ '6%' if is_multi_year else '10%' }};">Sl. No.</th>
					<th>Particulars</th>
					{% for label in table.year_labels %}
					<th style="width: {{ '11%' if is_multi_year else '18%' }};">{{ label }}</th>
					{% endfor %}
				</tr>
			</thead>
			<tbody>
				{% for row in table.rows %}
				<tr>
					<td class="sl">{{ loop.index }}</td>
					<td>{{ row.particulars }}</td>
					{% for amount in row.amounts %}
					<td class="amount">{{ amount }}</td>
					{% endfor %}
				</tr>
				{% endfor %}
				<tr class="total-row">
					<td></td>
					<td>{{ "Total Course Fee" if table.show_scholarship_row else ctx.total_label }}</td>
					{% for amount in table.total_row %}
					<td class="amount">{{ amount }}</td>
					{% endfor %}
				</tr>
				{% if table.show_scholarship_row %}
				<tr>
					<td></td>
					<td>Less: University Scholarship</td>
					{% for amount in table.scholarship_row %}
					<td class="amount">{{ amount if amount == "-" else "(" ~ amount ~ ")" }}</td>
					{% endfor %}
				</tr>
				<tr class="net-row">
					<td></td>
					<td>{{ ctx.total_label }}</td>
					{% for amount in table.net_row %}
					<td class="amount">{{ amount }}</td>
					{% endfor %}
				</tr>
				{% endif %}
			</tbody>
		</table>

		{% if ctx.bank_details_html %}
		<div class="bank-details">{{ ctx.bank_details_html }}</div>
		{% endif %}

		{% if ctx.closing_html %}
		<div class="closing-text">{{ ctx.closing_html }}</div>
		{% endif %}

		<div class="signature-block">
			{% if ctx.signature_image %}<img class="signature" style="width: auto !important; max-width: none !important; height: 24mm;" src="data:image/png;base64,{{ ctx.signature_image }}">{% endif %}
			{% if not (settings.cfo_signature and settings.signature_includes_designation) %}
			<div class="designation">{{ settings.cfo_designation or "Chief Finance Officer" }}</div>
			<div>{{ settings.institute_name or "" }}</div>
			{% endif %}
			{% if settings.seal_image %}<img class="seal" style="width: auto !important; max-width: none !important; height: 24mm;" src="data:image/png;base64,{{ get_file_b64(settings.seal_image) }}">{% endif %}
		</div>
	</div>
</td></tr>
<tr class="fc-layout-footer"><td>
	<div class="fc-footer">
		{% if ctx.footer_image %}
		<img src="data:image/png;base64,{{ ctx.footer_image }}">
		{% elif settings.footer_note %}
		<div class="footer-note">{{ settings.footer_note }}</div>
		{% endif %}
	</div>
</td></tr></tbody></table>
</div>
</body>
</html>
